    prev.x=cur.x;prev.y=cur.y;cur.x+=(tgt.x-cur.x)*a;cur.y+=(tgt.y-cur.y)*a;speed+=(tSpeed-speed)*o;tSpeed*=Math.exp(-8*dt);
    if(hovering&&speed>.01){lastActivity=elapsed;bufferEmpty=false;}
