      gl.uniform1f(u.uIsHovering,hovering?1:0);gl.uniform1f(u.uIsHolding,holding?1:0);gl.uniform1f(u.uGrainAmount,C.grainAmount);gl.uniform1f(u.uGrainScale,C.grainScale);gl.uniform2f(u.uTexelSize,1/rtA.w,1/rtA.h);
